using System;
using System.IO;
using System.Linq;
namespace Musikbox {
 public static class MediaMetadata {
  public static string Decode(string value){if(String.IsNullOrEmpty(value)||value.IndexOfAny(new[]{'Ã','Â','â'})<0)return value;try{string fixedValue=new System.Text.UTF8Encoding(false,true).GetString(System.Text.Encoding.GetEncoding(28591).GetBytes(value));return fixedValue.IndexOf('\uFFFD')<0?fixedValue:value;}catch{return value;}}
  public static Song Read(string path){using(var f=TagLib.File.Create(path)){var tag=f.Tag;var song=new Song{Source=path,Artist=String.Join("; ",tag.Performers),Title=tag.Title??"",Album=tag.Album??"",Year=tag.Year==0?"":tag.Year.ToString(),Genre=String.Join("; ",tag.Genres),Comment=tag.Comment??"",Track=tag.Track==0?"":tag.Track.ToString()+(tag.TrackCount>0?"/"+tag.TrackCount:""),Bitrate=f.Properties.AudioBitrate,TagType=TagSchema.Types(f),Duration=f.Properties.Duration.TotalSeconds};var id3=f.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;if(id3!=null){var aid=TagLib.Id3v2.UserTextInformationFrame.Get(id3,"Acoustid Id",false);if(aid==null)aid=TagLib.Id3v2.UserTextInformationFrame.Get(id3,"ACOUSTID_ID",false);if(aid!=null)song.AcoustidId=String.Join("; ",aid.Text);var trck=TagLib.Id3v2.TextInformationFrame.Get(id3,"TRCK",false);if(trck!=null&&trck.Text.Length>0)song.Track=trck.Text[0];}if(String.IsNullOrWhiteSpace(song.Title)){string name=Path.GetFileNameWithoutExtension(path);int n=name.IndexOf(" - ",StringComparison.Ordinal);if(n>0){if(String.IsNullOrWhiteSpace(song.Artist))song.Artist=name.Substring(0,n);song.Title=name.Substring(n+3);}else song.Title=name;}song.Artist=Decode(song.Artist);song.Title=Decode(song.Title);song.Album=Decode(song.Album);song.Genre=Decode(song.Genre);song.Comment=Decode(song.Comment);return song;}}
  public static void Write(string path,Song song,string album){using(var f=TagLib.File.Create(path)){f.Tag.Performers=String.IsNullOrWhiteSpace(song.Artist)?new string[0]:new[]{song.Artist};f.Tag.Title=song.Title??"";f.Tag.Album=album??"";uint year;f.Tag.Year=UInt32.TryParse(song.Year,out year)?year:0;GenreTags.Write(f,String.IsNullOrWhiteSpace(song.Genre)?new string[0]:song.Genre.Split(new[]{';'},StringSplitOptions.RemoveEmptyEntries));f.Tag.Comment=song.Comment??"";if(!String.IsNullOrEmpty(song.Artwork)){var picture=new TagLib.Picture(song.Artwork){Type=TagLib.PictureType.FrontCover};f.Tag.Pictures=new TagLib.IPicture[]{picture};}if(!String.IsNullOrEmpty(song.Track)){var parts=song.Track.Split('/');uint track,total;f.Tag.Track=UInt32.TryParse(parts[0],out track)?track:0;f.Tag.TrackCount=parts.Length>1&&UInt32.TryParse(parts[1],out total)?total:0;var id3=f.GetTag(TagLib.TagTypes.Id3v2,true) as TagLib.Id3v2.Tag;if(id3!=null)TagLib.Id3v2.TextInformationFrame.Get(id3,"TRCK",true).Text=new[]{song.Track};}f.Save();}}
  public static void WriteCopy(Song song,string album,string target,Action checkCancel){checkCancel();if(File.Exists(target))throw new IOException("Zieldatei existiert bereits: "+target);try{using(var input=File.OpenRead(song.Source))using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){checkCancel();output.Write(buffer,0,n);}}Write(target,song,album);checkCancel();}catch{try{File.Delete(target);}catch{}throw;}}
  public static void PreserveArtwork(string source,string target,Song song){if(MediaProbe57.Extensions.Contains(Path.GetExtension(source).ToLowerInvariant()))return;if(!String.IsNullOrEmpty(song.Artwork))return;using(var input=TagLib.File.Create(source)){if(input.Tag.Pictures.Length==0)return;using(var output=TagLib.File.Create(target)){if(output.Tag.Pictures.Length>0)return;output.Tag.Pictures=input.Tag.Pictures;output.Save();}}}
  public static byte[] Artwork(string path){using(var f=TagLib.File.Create(path)){var p=f.Tag.Pictures.FirstOrDefault();return p==null?null:p.Data.Data;}}
 }
}
